entries[148022] = { ["name"] = "Eiszapfen", ["text"] = "100 Meter Reichweite\nSofort\nBeim Einsatz von 'Frostblitz' oder 'Hagel' erhaltet Ihr einen Eiszapfen. Beim Einsatz von 'Eislanze' werden alle gespeicherten Eiszapfen auf das Ziel abgefeuert und verursachen jeweils (0.1% der Zaubermacht) Frostschaden.\n\nBis zu 5 Eiszapfen speicherbar. Überzählige Eiszapfen werden automatisch abgefeuert.\n\nErhöht den Schaden von 'Gefrorene Kugel', 'Blizzard', und 'Kometenhagel' um 13%.\n\nErhöht den Schaden von 'Eislanze', 'Gletscherstachel' und 'Froststrahl' um 8%." }
