entries[148266] = { ["name"] = "Glyphe 'Skelett'", ["text"] = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nBeruf:\nInschriftenkunde (75)\nEntdeckung:\nForschung: Mitternachtstinte\n\nKlassen: Todesritter\n11" }
entries[148270] = { ["name"] = "Glyphe 'Unbändiger Elementar'", ["text"] = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nBeruf:\nInschriftenkunde (150)\nEntdeckung:\nForschung: Jadefeuertinte\n\nKlassen: Magier\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Wasserelementar wird durch einen unbändigen Wasserelementar ersetzt. Exklusiv mit: Glyphe 'Verdampfen' Glyphe 'Gezeiten' Glyphe 'Sturmwacht' Glyphe 'Finstere Tiefe' Glyphe 'Dampfende Wut' Glyphe 'Kältewellen'\n11" }
entries[148271] = { ["name"] = "Glyphe 'Verdampfen'", ["text"] = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nBeruf:\nInschriftenkunde (100)\nEntdeckung:\nForschung: Löwentinte\n\nKlassen: Magier\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Größe Eures Wasserelementars um 15%. Exklusiv mit: Glyphe 'Unbändiger Elementar' Glyphe 'Gezeiten' Glyphe 'Sturmwacht' Glyphe 'Finstere Tiefe' Glyphe 'Dampfende Wut' Glyphe 'Kältewellen'\n11" }
entries[148274] = { ["name"] = "Glyphe 'Säule des Lichts'", ["text"] = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nBeruf:\nInschriftenkunde von Pandaria (1)\nEntdeckung:\nForschung: Traumtinte\n\nKlassen: Paladin\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nKritische Heilungen von 'Heiliger Schock' bei anderen Spielercharakteren erzeugen kurzzeitig eine Lichtsäule an deren Standort.\n11" }
entries[148275] = { ["name"] = "Glyphe 'Engel'", ["text"] = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nBeute von:\nWeltkreaturen\n\nKlassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nBeim Wirken von Heilzaubern besteht eine Chance, dass Ihr Engelsflügel erhaltet. (Procchance: 15%)\n11" }
