entries[148278] = { ["name"] = "Glyphe 'Inspirierte Hymnen'", ["text"] = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mondlichttinte (3)\nBeruf:\nInschriftenkunde (25)\nEntdeckung:\nForschung: Mondlichttinte\n\nKlassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Ihr Hymnen kanalisiert, erscheint ein Geist über Euch.\n11" }
entries[148281] = { ["name"] = "Glyphe 'Geisterraptoren'", ["text"] = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nBeruf:\nInschriftenkunde (100)\nEntdeckung:\nForschung: Löwentinte\n\nKlassen: Schamane\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Geisterwölfe werden durch Geisterraptoren ersetzt.\n11" }
